// An app's own icons, merged in at module load. A name already here is overwritten, which is the
// only way an app could redraw a shared convention - so don't.
export const addIcons = table => Object.assign(ICON, table);

export function icon(name) {
  const spec = ICON[name];
  const svg = document.createElementNS(NS, 'svg');
  svg.setAttribute('viewBox', '0 0 16 16');
  svg.setAttribute('aria-hidden', 'true');
  const p = document.createElementNS(NS, 'path');
  p.setAttribute('d', spec.d);
  if (spec.stroke) {
    p.setAttribute('fill', 'none');
    p.setAttribute('stroke', 'currentColor');
    p.setAttribute('stroke-width', String(spec.stroke));
    p.setAttribute('stroke-linecap', 'round');
    p.setAttribute('stroke-linejoin', 'round');
  } else {
    p.setAttribute('fill', 'currentColor');
    // A second subpath drawn inside the first is a hole rather than an overlap: the one way an
    // icon can be a filled shape with a figure knocked out of it, which is what a stage reading
    // its colour as a fill needs.
    if (spec.rule) p.setAttribute('fill-rule', spec.rule);
  }
  svg.append(p);
  return svg;
}

// `name` is an icon name, or any other string to use as a glyph. An icon row is icons
// throughout; a `24h` or a `!` is a character, because there is no icon for either.
export function iconBtn(name, label, cls = '') {
  const b = el('button', ['ib', cls].filter(Boolean).join(' '));
  b.type = 'button';
  b.title = label;
  b.setAttribute('aria-label', label);
  b.append(ICON[name] ? icon(name) : el('span', 'glyph', name));
  return b;
}

// ---- overlays ------------------------------------------------------------------------------
// Three mechanisms. `openPop` hangs a dropdown off the button that opened it. `openCentred` is a
// panel or a preview, centred by the stylesheet and only unhidden. `openRowPop` is the third and
// the odd one: a field's popup inside a modal, which carries **no scrim**, so the tap that
// dismisses it still reaches the row it landed on and moving from one field to the next is one
// tap rather than two. That is the whole reason it is not one of the other two.
//
// `#scrim` is a convention: an app that opens overlays has one, and the base stylesheet styles
// it. The pops an app closes together are the ones it registers.

let POPS = [];

// Every overlay this app closes with closePops(), as selectors. Called once, at boot.
}

// One row of icons under the when, and the whole of the popup's small print: all-day, the
// stage, important, the category, the repetition and the alerts, with no names beside them.
// Six icons are one line at 320px where six named rows are most of a screen, and the popup is
// opened far more often to read an entry than to fill one in.
//
// **A tap on an icon is the tap on its row.** The two toggles flip where they stand, the stage
// cycles, and the three fields open the same popup their line opens - so the chevron below
// changes what is written down, never what anything does.
function quickRow() {
  const bar = el('div', 'iconbar quick');
  bar.append(allDayBtn());
  if (D.type === 'task') bar.append(stageBtn());
  bar.append(bangBtn());
  for (const f of FIELDS.filter(f => ICON_FIELDS.includes(f.k)
    && (f.k !== 'recurrence' || canRule()))) bar.append(quickBtn(f));
  bar.append(el('span', 'spacer'), expandBtn());
  return bar;
}

// A field as an icon: lit when it holds something, because with the name gone the lit state is
// all that is left to say so, and the value itself is in the label a screen reader and a hover
// both read.
//
// **A lit icon lights in its field's own colour**, which is `--on` - the category's colour for
// the category, the accent for every other field. The category is the one that says more again:
// the ball on top is knocked out in whatever reads on that colour, so the icon carries the
// category twice over and does not need a name beside it.
function quickBtn(f) {
  const v = readField(f);
  const set = f.set(v);
  const b = iconBtn(f.ic, `${f.label}${set ? `: ${f.sum(v)}` : ''}`,
    set || popped === f.k ? 'on' : '');
  b.dataset.field = f.k;
  if (f.k === 'group' && D.v.group) {
    const c = colorOf(D.v.group);
    b.style.setProperty('--on', c);
    b.querySelector('svg').style.color = inkOn(c);
  } else {
    b.style.setProperty('--on', 'var(--link)');
  }
  b.addEventListener('click', () => openField(f, 'quick'));
  return b;
}

// The chevron: down for a row of icons, up for the lines. It is remembered per device, like the
// board's orientation - someone who wants the names wants them every time - and it is both the
// way out and the way back in, which is the rule every switch in Mine holds to.
function expandBtn() {
  const open = S.prefs.popupExpanded;
  const b = iconBtn('chev', open ? 'Hide the field names' : 'Show the field names',
    `more${open ? ' open' : ''}`);
  b.setAttribute('aria-expanded', String(open));
  b.addEventListener('click', () => {
    S.prefs.popupExpanded = !open;
    redraw();
    setKV('calendar.popupExpanded', !open);
  });
  return b;
}

// All-day and important on one line: two yeses and noes, each an icon and its word, lit when on
// and plain when off. There is nothing to clear and nothing to open, so the line carries neither
// a trashcan nor an x - and neither value fills a row of its own.
function chipsRow() {
  const row = el('div', 'frow chips');
  row.append(chip('24h', 'All-day', D.allDay, toggleAllDay, 'var(--link)'),
    chip('!', 'Important', D.important,
      () => { D.important = !D.important; redraw(); }, 'var(--bad)'));
  return row;
}

// The same two values the icons above carry, and the same colours: a lit chip is a tint of its
// own `--on` rather than a solid, because a chip carries a word as well as a glyph.
function chip(glyph, text, on, onClick, colour) {
  const b = el('button', `fchip${on ? ' on' : ''}`);
  b.style.setProperty('--on', colour);
  b.type = 'button';
  b.setAttribute('aria-pressed', String(on));
  b.setAttribute('aria-label', text);
  b.append(el('span', 'glyph', glyph), el('span', '', text));
  b.addEventListener('click', onClick);
  return b;
}

// The stage as a line, reading the stage it is in. Tapping it cycles, exactly as the icon above
// does: a list of three would be a second way to set one value, and the line is a name for what
// the colour already says.
function stageRow() {
  const row = el('div', 'frow');
  row.dataset.field = 'stage';
  const ic = icon('ticked');
  ic.style.color = STAGE_COLOR[D.stage];
  row.append(ic, tap(STAGE_LABEL[D.stage], false, '', cycleStage,
    `Stage: ${STAGE_LABEL[D.stage]}`));
  return row;
}

// All-day is a clickable control rather than a checkbox, and it lights with the ordinary enabled
// background - deliberately not the disk's green, which in Mine means a save.
//
// It reads `24h` rather than carrying an icon: every drawing of a whole day reads as something
// else, and the sun this replaces was taken for weather. Only the button says `24h` - the grids'
// strip and the prose still say all-day, which is the clearer word where there is room for it.
function allDayBtn() {
  const b = iconBtn('24h', 'All-day', D.allDay ? 'on' : '');
  b.style.setProperty('--on', 'var(--link)');
  b.setAttribute('aria-pressed', String(D.allDay));
  b.addEventListener('click', toggleAllDay);
  return b;
}

function toggleAllDay() {
  D.allDay = !D.allDay;
  if (D.allDay) { D.startTime = ''; D.endTime = ''; }
  else { D.startTime = D.startTime || '09:00'; D.endTime = D.endTime || '10:00'; }
  redraw();
}

// Stage and important are two small values rather than fields with a form each, so they are
// edited in the row itself. Stage is a ticked square carrying its own colour - the badge on its
// corner was a 16px icon with a 9px dot on it, and the colour it carried is the whole of what
// the badge was for. Important has nothing to colour and lights instead.
function stageBtn() {
  const b = iconBtn('ticked', `Stage: ${D.stage}`);
  b.querySelector('svg').style.color = STAGE_COLOR[D.stage];
  b.addEventListener('click', cycleStage);
  return b;
}

function cycleStage() {
  D.stage = STAGES[(STAGES.indexOf(D.stage) + 1) % STAGES.length];
  redraw();
}

// A toggle, not a cycle: there is no third state to reach, and no badge, because the lit state
// has already said everything a yes or no has to say.
function bangBtn() {
  const b = iconBtn('!', 'Important', D.important ? 'on' : '');
  // The red importance is drawn in everywhere else - the `!` on a card, the trashcan - so lit
  // importance is that red rather than the accent the other icons light in.
  b.style.setProperty('--on', 'var(--bad)');
  b.setAttribute('aria-pressed', String(D.important));
  b.addEventListener('click', () => { D.important = !D.important; redraw(); });
  stands; each step writes into the draft as it is picked, like every other editor in this popup,
  so there is nothing to accept at the end of one — and still nothing is written to the repo
  until the disk.

The when-line no longer repeats the stage and the importance as words. The toggle row shows both,
live, directly beneath it.

### The quick row, and the chevron

**One row of icons directly under the when, carrying everything small the entry holds**: `24h`,
the stage, `!`, the category, the repetition and the alerts — six icons, no names, one line at
320px. Six named rows are most of a phone screen, and the popup is opened to read an entry far
more often than to fill one in.

Location, participants and details are **not** in it. A pin standing in for an address says only
that there is one, which is what a row of icons is for and what those three are not; they are
lines whether the chevron is open or shut.

**A tap on an icon is the tap on its row.** All-day and important flip where they stand, the
stage cycles, and the category, the repetition and the alerts open exactly the popup their line
opens — anchored under the icon that was tapped. So the chevron changes what is written down,
never what anything does.

**The chevron at the end of the row shows the names**, as lines beneath it, in the order the
icons are in: `24h` and `!` as two chips on one line, then the stage reading `Todo`, `Doing` or
`Done`, then the category, the repetition and the alerts. The icons stay above them — a field
having two ways in is already true of a grid line and a kanban card, and the row is where the
chevron lives. **It is remembered per device**, like the board's orientation: someone who wants
the names wants them every time. It is both the way out and the way back in, which is the rule
every switch in Mine holds to.

**The two toggles and the stage are not fields with an editor each**: they are small values,
edited where they stand with a single tap, and each **shows its value** rather than merely
whether it has one. A tap is the whole edit, into the draft like everything else — there is
nothing in these three to type, so there is nothing for a row's `x` to put back and no editor to
open. The disk appears on the first tap, as it does for any other change.

- **`24h` for all-day** — the one control in the popup that is a word rather than a picture, and
  deliberately so: every drawing of a whole day reads as something else. The sun it replaces was
  taken for weather or for daylight hours, and `24h` cannot be. **A clickable control, not a
  checkbox** — lit when on, plain when off. On an event it is alone on the row. Only the button
  changes its name: the strip in the week and day grids still reads `all-day`, and so does this
  document, because the word is the clearer one in prose and the button is the one place with no
  room for it.
- a **ticked square with the tick knocked out** for **stage** — cycles `todo` → `doing` → `done`
  on each tap, drawn in that stage's kanban colour: red, yellow, green. It is the type marker's
  ticked square *filled in*, so colour and fill tell the two apart rather than a second drawing;
  the badge it replaces was a 9px dot on a 16px corner carrying the one thing the icon can carry
  itself. There is no stage popup — a list of three would be a second way to set one value — and
  its line under the chevron reads the word and cycles too.
- a `!` for **important** — a straight toggle, lit when the task is important and plain when it
  is not. It carries no badge: a yes or no has nothing a badge could add that the lit state has
  not already said, which is what made the old flag need a digit and this one not.

On an event the stage is not there at all, because an event has none. `24h` and `!` are on every
