// The weekday letters and six rows of day buttons, drawn once for the three places that pick a
// date: the pane's dropdown, the when's date steps and the repetition's end date. Today is
// marked, so is the day the picker is set to, and `highlight` marks one more - the start date,
// while the end date is being chosen, so the day the end may not fall before is visible in the
// grid itself.
//
// It returns the cells rather than a box of its own, because `.pick-body` is the grid and a div
// between it and its cells would collapse the layout. The caller owns the month it is looking
// at and pages it: the pane's dropdown pages from the head it already has, a field's popup from
// a line in its body, and neither can be the other's.
export const monthDays = (y, m, { value, highlight, onPick }) => [
  ...weekLetters().map(([n]) => el('span', 'wh', n)),
  ...monthGrid(y, m, S.prefs.weekStart).map(k => {
    const [, mm, dd] = partsOf(k);
    const b = el('button', ['pk', mm !== m + 1 ? 'out' : '', k === value ? 'sel' : '',
      k === highlight ? 'hl' : '', k === todayKey() ? 'now' : ''].filter(Boolean).join(' '),
      String(dd));
    b.type = 'button';
    b.addEventListener('click', () => onPick(k));
    return b;
  })
];

// ---- the calendar's icons ------------------------------------------------------------------
// Its own subjects, drawn on the same 16x16 box and merged into the shared set at load. The
// verbs - a trashcan, a save, an x, a plus, a chevron, the hamburger, the gear, the clock, the
// house - are in ../shared/ui.js, because a second app drawing its own is how the conventions
// REQUIREMENTS.md states for all of Mine would quietly stop being conventions.
addIcons({
  repeat: { d: 'M2.6 8.4A5.4 5.4 0 0 1 12.6 5.6M13.4 7.6A5.4 5.4 0 0 1 3.4 10.4M12.9 2.6v3.2H9.7M3.1 13.4v-3.2h3.2', stroke: 1.5 },
  ball:   { d: 'M8 3.1a4.9 4.9 0 1 0 0 9.8 4.9 4.9 0 0 0 0-9.8z', stroke: 1.4 },
  cal:    { d: 'M2.8 4.6h10.4v8.8H2.8zM2.8 7.4h10.4M5.6 2.6v3M10.4 2.6v3', stroke: 1.4 },
  pin:    { d: 'M8 1.9a4.2 4.2 0 0 0-4.2 4.2c0 3.2 4.2 8.1 4.2 8.1s4.2-4.9 4.2-8.1A4.2 4.2 0 0 0 8 1.9zM8 7.7a1.7 1.7 0 1 0 0-3.4 1.7 1.7 0 0 0 0 3.4z', stroke: 1.3 },
  bell:   { d: 'M8 2.1a3.4 3.4 0 0 0-3.4 3.4v2.3L3.3 10.2h9.4l-1.3-2.4V5.5A3.4 3.4 0 0 0 8 2.1zM6.4 11.6a1.6 1.6 0 0 0 3.2 0', stroke: 1.4 },
  person: { d: 'M8 2.7a2.5 2.5 0 1 0 0 5 2.5 2.5 0 0 0 0-5zM3.1 13.7c0-2.8 2.4-4.5 4.9-4.5s4.9 1.7 4.9 4.5', stroke: 1.4 },
  filter: { d: 'M2.5 3.3h11l-4.2 5.2v5.1L6.7 12.3V8.5z', stroke: 1.4 },
  // A ticked square for task, a calendar page for event: the icon row carries no letters.
  check:  { d: 'M13.4 3.4v9.2H2.6V3.4h10.8M5.3 8.1l2.1 2.2 4.2-4.5', stroke: 1.5 },
  // The stage: a filled square with a tick knocked out of it, carried in the stage's own colour
  // - red, yellow, green. It is `check` filled in: the two are told apart by colour and by fill,
  // which is how the category's ball tells one group from another, rather than by a badge on a
  // 16px corner. All-day and important are the words `24h` and `!`, which iconBtn renders as
  // glyphs - there is no icon for either, deliberately: the sun was taken for weather and a flag
  // needed a digit.
  ticked: { d: 'M2.6 3.4h10.8v9.2H2.6zM6.9 11.6 3.6 8.3 5 6.9 6.9 8.8 11 4.7 12.4 6.1Z',
            rule: 'evenodd' },
  // The two ways out of a view: the board, and the zoom that picks a period by name.
  board:  { d: 'M2.6 3.6h10.8v8.8H2.6zM6.2 3.6v8.8M9.8 3.6v8.8', stroke: 1.4 },
  zoom:   { d: 'M7.1 2.4a4.7 4.7 0 1 0 0 9.4 4.7 4.7 0 0 0 0-9.4zM10.6 10.6 14 14', stroke: 1.5 }
});
// path cannot fail to load.
//
// What is in here is the vocabulary shared across Mine - the verbs every app needs, and the two
// conventions REQUIREMENTS.md states for all of them: a save is a green disk and a trashcan is a
// red trashcan. A second app drawing its own trashcan path is how that convention would quietly
// stop being one. An app's own subjects - the calendar's recurrence, its stages - are registered
// by that app with addIcons().

// Drawn as outlines rather than solids: a stroked glyph is what carries Mine's paper look, and
// at 1.2-1.4 it stays legible at 16px. The one deliberate solid is the calendar's `ticked`, which
// is `check` filled in and would otherwise be the same drawing as it.
const NS = 'http://www.w3.org/2000/svg';
const ICON = {
  trash:  { d: 'M3 5.2h10M6.4 5.2V3.4h3.2v1.8M4.7 5.2l.5 8.4h5.6l.5-8.4M6.8 7.6v3.4M9.2 7.6v3.4', stroke: 1.3 },
  disk:   { d: 'M3.2 3.2h7.3l2.3 2.4v7.2H3.2zM5.7 3.2v3.3h4V3.2M5.7 9.3h4.6v3.5H5.7', stroke: 1.3 },
  pen:    { d: 'M11.4 2.1l2.5 2.5-7.7 7.7-3.3.8.8-3.3zM9.6 3.9l2.5 2.5', stroke: 1.3 },
  plus:   { d: 'M8 3v10M3 8h10', stroke: 1.8 },
  x:      { d: 'M4 4l8 8M12 4l-8 8', stroke: 1.8 },
  chev:   { d: 'M10 3.5 5.5 8l4.5 4.5', stroke: 1.8 },
  // Three lines of text: a details row, or a markdown body. Every app keeps one.
  lines:  { d: 'M3 4.6h10M3 8h10M3 11.4h6.4', stroke: 1.6 },
  // Three lines of equal length for the hamburger, so `lines` keeps meaning details and no icon
  // means two things.
  menu:   { d: 'M2.4 4.4h11.2M2.4 8h11.2M2.4 11.6h11.2', stroke: 1.6 },
  // A clock face for the logs: the panel's subject is when the last attempt ran and how long the
  // queue has been waiting. A stack of lines would read as details, which `lines` already means.
  logs:   { d: 'M8 2.6a5.4 5.4 0 1 0 0 10.8A5.4 5.4 0 0 0 8 2.6zM8 5.1V8.3l2.5 1.6', stroke: 1.5 },
  house:  { d: 'M2.5 7.3 8 2.5l5.5 4.8V13.5H9.6V9.7H6.4v3.8H2.5z', stroke: 1.4 },
  gear:   { d: 'M8 5.6a2.4 2.4 0 1 0 0 4.8 2.4 2.4 0 0 0 0-4.8zM7.1 1.4h1.8l.3 1.7 1.2.5 1.4-1 1.3 1.3-1 1.4.5 1.2 1.7.3v1.8l-1.7.3-.5 1.2 1 1.4-1.3 1.3-1.4-1-1.2.5-.3 1.7H7.1l-.3-1.7-1.2-.5-1.4 1-1.3-1.3 1-1.4-.5-1.2-1.7-.3V7.1l1.7-.3.5-1.2-1-1.4 1.3-1.3 1.4 1 1.2-.5z', stroke: 1.2 }
};

// An app's own icons, merged in at module load. A name already here is overwritten, which is the
// only way an app could redraw a shared convention - so don't.
export const addIcons = table => Object.assign(ICON, table);

export function icon(name) {
  const spec = ICON[name];
  const svg = document.createElementNS(NS, 'svg');
  svg.setAttribute('viewBox', '0 0 16 16');
  svg.setAttribute('aria-hidden', 'true');
  const p = document.createElementNS(NS, 'path');
  p.setAttribute('d', spec.d);
  if (spec.stroke) {
    p.setAttribute('fill', 'none');
    p.setAttribute('stroke', 'currentColor');
    p.setAttribute('stroke-width', String(spec.stroke));
    p.setAttribute('stroke-linecap', 'round');
    p.setAttribute('stroke-linejoin', 'round');
  } else {
    p.setAttribute('fill', 'currentColor');
    // A second subpath drawn inside the first is a hole rather than an overlap: the one way an
    // icon can be a filled shape with a figure knocked out of it, which is what a stage reading
    // its colour as a fill needs.
    if (spec.rule) p.setAttribute('fill-rule', spec.rule);
  }
  svg.append(p);
  return svg;
}

// `name` is an icon name, or any other string to use as a glyph. An icon row is icons
// throughout; a `24h` or a `!` is a character, because there is no icon for either.
export function iconBtn(name, label, cls = '') {
  const b = el('button', ['ib', cls].filter(Boolean).join(' '));
  b.type = 'button';
  b.title = label;
  b.setAttribute('aria-label', label);
  b.append(ICON[name] ? icon(name) : el('span', 'glyph', name));
  return b;
}

// ---- overlays ------------------------------------------------------------------------------
// Three mechanisms. `openPop` hangs a dropdown off the button that opened it. `openCentred` is a
// panel or a preview, centred by the stylesheet and only unhidden. `openRowPop` is the third and
// the odd one: a field's popup inside a modal, which carries **no scrim**, so the tap that
// dismisses it still reaches the row it landed on and moving from one field to the next is one
// tap rather than two. That is the whole reason it is not one of the other two.
//
// `#scrim` is a convention: an app that opens overlays has one, and the base stylesheet styles
// it. The pops an app closes together are the ones it registers.

let POPS = [];

// Every overlay this app closes with closePops(), as selectors. Called once, at boot.

