// column header.

for (const [id, name] of [['#home', 'house'], ['#zoom-btn', 'zoom'], ['#menu-btn', 'menu'],
  ['#day-add', 'plus'], ['#day-close', 'x'], ['#sub-close', 'x'], ['#settings-close', 'x'],
  ['#filter-close', 'x'], ['#filter-sub-close', 'x'], ['#fpop-close', 'x'], ['#logs-close', 'x']])
  $(id).append(icon(name));

// ---- the hamburger's menu ------------------------------------------------------------------
// Three errands behind one button, each named before it is opened and each opening on its own.
eq('there is no gear and no filter button in the pane',
  await ev(`document.querySelectorAll('#gear, #filter-btn').length`), 0);
await menu();
eq('the hamburger opens a menu naming its three errands', await ev(
  `(() => { const p = document.querySelector('#menu-pop');
    return !p.hidden && [...p.querySelectorAll('.mrow')].map(b => b.textContent); })()`),
  ['filter', 'settings', 'logs']);
eq('and opens none of them yet', await ev(
  `[document.querySelector('#filter-pop').hidden,
    document.querySelector('#settings-panel').hidden,
    document.querySelector('#logs-panel').hidden]`), [true, true, true]);
eq('the menu hangs off the hamburger, within its right edge', await ev(
  `(() => { const b = document.querySelector('#menu-btn').getBoundingClientRect();
    const p = document.querySelector('#menu-pop').getBoundingClientRect();
    return [p.top > b.bottom, Math.round(p.right) <= Math.round(b.right) + 1]; })()`),
  [true, true]);

await menu('filter');
eq('filter opens the filter alone', await ev(
  `[document.querySelector('#filter-pop').hidden,
    document.querySelector('#settings-panel').hidden,
    document.querySelector('#menu-pop').hidden]`), [false, true, true]);
// Hanging off the hamburger rather than centred: the view it narrows has to stay in sight while
// it is narrowed, which a centred card over the middle of the screen cannot do.
ok('and hangs off the hamburger rather than being centred', await ev(
  `(() => { const b = document.querySelector('#menu-btn').getBoundingClientRect();
    const p = document.querySelector('#filter-pop').getBoundingClientRect();
    return p.top > b.bottom && p.top < b.bottom + 20; })()`), 'the filter is not under the button');
// The groups are no longer folded away: that fold existed only because an open list pushed the
// nine settings rows below the fold, and the settings are not in here any more.
const groups = await ev(`({
  drop: document.querySelectorAll('#filter-body .gdrop').length,
  shown: document.querySelectorAll('#filter-body .glab.grp').length,
  swatches: document.querySelectorAll('#filter-body .glab.grp .swatch').length
})`);
eq('the groups are listed, not folded behind a dropdown', groups.drop, 0);
ok('a checkbox per group, straight away', groups.shown >= 3, `${groups.shown} checkboxes`);
eq('each showing its colour', groups.swatches, groups.shown);
await ev(`document.querySelectorAll('#filter-body .glab.grp input')[0].click()`);
await sleep(500);
const ticks = await ev(
  `[...document.querySelectorAll('#filter-body .glab.grp input')].map(i => i.checked)`);
eq('unticking one leaves the rest on', [ticks[0], ticks.slice(1).every(Boolean)], [false, true]);
await ev(`document.querySelectorAll('#filter-body .glab.grp input')[0].click()`);
await sleep(500);
await ev(`document.querySelector('#scrim').click()`);
await sleep(250);
// The settings panel holds the nine rows and nothing else: no filter section above them, so the
// last of them is above the fold at 320px with nothing to push it down.
await viewport(320);
await menu('settings');
eq('settings opens the panel alone, with no filter section in it', await ev(
  `[document.querySelector('#settings-panel').hidden,
    document.querySelector('#filter-pop').hidden,
    document.querySelector('#settings-panel').querySelectorAll('#filter-body').length]`),
  [false, true, 0]);
const fold = await ev(`(() => {
  const rows = document.querySelectorAll('#settings-body .srow');
  const last = rows[rows.length - 1].getBoundingClientRect();
  const panel = document.querySelector('#settings-panel').getBoundingClientRect();
  return Math.round(last.bottom - panel.bottom);
})()`);
ok('the ninth settings row stays above the fold at 320px', fold <= 2, `${fold}px past it`);
await ev(`document.querySelector('#scrim').click()`);
await sleep(250);

await viewport(900);
await open('K');
await menu('filter');
const boardFilter = await ev(`({
  important: [...document.querySelectorAll('#filter-body .glab.imp')].map(c => c.textContent),
  selects: document.querySelectorAll('#filter-body select').length
})`);
eq('the board filter has one important switch, not four chips', boardFilter.important,
  ['!important only']);
ok('and still an assignee', boardFilter.selects >= 1, 'no assignee select on the board filter');
await ev(`document.querySelector('#scrim').click()`);
await sleep(250);

await viewport(900);
await open();
await menu('filter');
// The assignee is the board's own; importance is not any more, so only the select goes.
eq('and the assignee is not in a calendar view', await ev(
  `document.querySelectorAll('#filter-body select').length`), 0);
eq('while important only is', await ev(
  `document.querySelectorAll('#filter-body .glab.imp').length`), 1);
await ev(`document.querySelector('#scrim').click()`);
await sleep(250);

eq('the pane dropped Today, +, D W M Y K and the zoom pair',
reading its start on the first and its end **arrowed** on the last, and that the strip's corner
no longer says `all-day`. That the day preview for a day in the **middle** of a span lists it.

**The filter, and the count on the hamburger.** That the dropdown lists the groups, then the
three stages and `important only`. That switching a stage off **hides those tasks from the month
view** and leaves every event where it was; that `important only` keeps what is marked, **events
included**, and drops what is not. That the hamburger carries **one per kind of narrowing** — two
switches on reads `2`, not the number of things hidden — that it is empty when nothing is
filtered, and that **both survive a reload**, which is what the per-device storage is for.

**That the `x` is the rightmost control in every popup**: the entry popup, each active row, each
agree in both
directions: nothing typed means no disk and no prompt, something typed means both.

**The hamburger's menu.** That **one button still covers both and opens neither**: the hamburger
is the only way in, there is no gear and no filter button anywhere in the pane, and one tap opens
a menu whose rows read `filter` and `settings` with the filter dropdown and the settings panel
both still hidden. That the menu hangs under the hamburger and within its right edge, read from
the two bounding boxes. That tapping `filter` opens the filter **alone** and tapping `settings`
opens the panel **alone**, each with the other and the menu hidden — a check that fails the moment
the two are merged back into one overlay. That the filter hangs under the hamburger rather than
being centred, because the view it narrows has to stay in sight while it is narrowed.

**The settings panel.** That it holds the nine rows and **no filter section** — `#filter-body` is
not inside it. That the nine are two halves — every label's box in the left half of the row and
every control's box in the right — so the controls' left edges all agree, which is the one
measurement that separates the new panel from the old. That no label wraps to a second line at
320 px. That **groups are not listed in it**: it holds one *edit groups* button, which opens the
same list the category row opens, and that **only this way in carries the pen, the trashcan and
the `+ add`** — reached from an entry the same list has none of the three and no `no category` row
either, which is the check that keeps the two forms apart. That the panel's last element is a
settings row and **not a paragraph of explanation**. That the last of the nine rows is **above the
fold at 320 px**, which is now unobstructed: there is no filter section above them to push them
off the screen.

**The popup is centred.** At 320 px, that the entry popup — with its tallest row active, the
details body's textarea — the settings panel and the day preview each sit clear of the bottom
edge — their bounding box's bottom is above the
viewport's, and their top below it. Nothing in the app is a bottom sheet any more, and a card
that still stretches to the bottom edge is the old sheet in new paint. **And the day preview is
centred on a desktop too**, measured at 900 px, because it is no longer anchored to the cell that
opened it — the check that catches a third overlay mechanism growing back.

**The filter dropdown.** That the groups are **listed, not folded**: there is no `groups`
dropdown row and a checkbox per group, each with its colour, is there straight away. That ticking
two of them still shows two groups and hides the rest, because a list is no excuse for the filter
having become single-select. That on the board the filter adds an assignee and **one** important
toggle, that neither appears in a calendar view, and that no `P1`, `P2` or `P3` chip is left
anywhere in it.

calendar/ui.js        DOM helpers, the icon set, and the state every view reads
calendar/views.js     year, month, week, day, and the day preview
calendar/kanban.js    the board
calendar/popup.js     the one entry popup: its rows, their inline editors, their writes
calendar/settings.js  the filter dropdown, the settings panel and the logs panel: the hamburger's
                      three errands
calendar/app.js       the top pane, navigation, the picker, the zoom, the menu, the sync line
shared/prefs.js       theme and date format, which belong to Mine rather than to one app
```

